const j = $json;
const headers = {};
for (const h of (j.payload?.headers || [])) headers[String(h.name).toLowerCase()] = String(h.value || '');
for (const [k,v] of Object.entries(j.headers || {})) headers[k.toLowerCase()] = String(v || '');
function field(name, ...values) {
  return headers[name] || values.find(v => typeof v === 'string' && v.trim()) || '';
}
function addr(v) {
  if (typeof v === 'string') return v;
  return v?.text || v?.value?.map(a => a.address).join(', ') || '';
}
const from = field('from', j.From, addr(j.from));
const replyTo = field('reply-to', j['Reply-To'], addr(j.replyTo));
const subject = field('subject', j.Subject, j.subject);
const plain = [], html = [];
let attachments = Boolean(j.attachments?.length);
function walk(p) {
  if (!p) return;
  if (p.filename || p.body?.attachmentId) attachments = true;
  if (!p.filename && p.body?.data && /^(text\/plain|text\/html)$/i.test(p.mimeType || '')) {
    const text = Buffer.from(p.body.data.replace(/-/g,'+').replace(/_/g,'/'), 'base64').toString('utf8');
    (p.mimeType.toLowerCase() === 'text/plain' ? plain : html).push(text);
  }
  for (const part of (p.parts || [])) walk(part);
}
walk(j.payload);
function cleanHtml(s) {
  return String(s).replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,'').replace(/<\s*br\s*\/?\s*>/gi,'\n').replace(/<\/p>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>');
}
const body = String(j.text || j.textPlain || plain.join('\n') || cleanHtml(j.html || j.textHtml || html.join('\n')) || '').trim();
const address = (from.match(/<([^<>\s]+@[^<>\s]+)>/) || from.match(/([^\s<>]+@[^\s<>]+)/))?.[1] || '';
const auto = field('auto-submitted');
const precedence = field('precedence');
const list = field('list-id', j['List-ID']) || field('list-unsubscribe', j['List-Unsubscribe']);
const labels = (j.labelIds || j.labels || []).map(v => typeof v === 'string' ? v : v.id);
const account = $('Validar configuracao').item.json.email_automacao;
let reason = '';
if (address.toLowerCase() === account) reason = 'Mensagem do próprio endereço da automação';
if (!reason && labels.some(v => ['SENT','DRAFT','SPAM','TRASH'].includes(v))) reason = 'Mensagem enviada, rascunho, spam ou lixeira';
else if (auto && auto.toLowerCase() !== 'no') reason = 'Mensagem automática';
else if (/^(bulk|list|junk)$/i.test(precedence) || list) reason = 'Lista de distribuição ou publicidade automática';
else if (/(^|[\s<])(no[-_.]?reply|do[-_.]?not[-_.]?reply|mailer-daemon|postmaster)@/i.test(from)) reason = 'Remetente automático';
let review = '';
if (!j.id) review = 'ID original ausente';
else if (!address) review = 'Remetente inválido';
else if (!body) review = 'Corpo completo indisponível; snippet não é suficiente';
else if (body.length > 40000) review = 'Mensagem excede limite de análise';
return {json:{email_automacao:account,id_email:j.id || '',thread_id:j.threadId || '',remetente:from,reply_to:replyTo,assunto_email:subject,corpo_email:body,tem_anexos:attachments,elegivel:!reason && !review,decisao:reason?'nao_responder':review?'revisao_humana':'',motivo:reason || review}};

const source = $('Preparar analise').item.json;
let parsed, issue = '';
try {
  let raw = $json.text ?? $json.output ?? '';
  if (typeof raw === 'string') {
    raw = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
    parsed = JSON.parse(raw);
  } else parsed = raw;
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Objeto JSON esperado');
  const decisions = ['responder','nao_responder','revisao_humana'];
  const categories = ['comercial_geral','qualitcontrol_sgq','qualitcontrol_sst','manut_control','gestao_redes_supermercados','erp_integracao','precos_contratacao','suporte_tecnico','outros'];
  if (!decisions.includes(parsed.decisao) || !categories.includes(parsed.categoria)) throw new Error('Decisão ou categoria inválida');
  if (typeof parsed.motivo !== 'string' || !parsed.motivo.trim()) throw new Error('Motivo ausente');
  if (typeof parsed.resposta_html !== 'string') throw new Error('Resposta HTML inválida');
  if (parsed.decisao === 'responder') {
    if (!source.elegivel || !source.id_email) throw new Error('Mensagem não elegível');
    if (!parsed.resposta_html.replace(/<[^>]+>/g,'').trim() || parsed.resposta_html.length > 20000) throw new Error('Resposta vazia ou excessiva');
    const tags = parsed.resposta_html.match(/<[^>]*>/g) || [];
    if (tags.some(t => !/^<\/?(?:p|br|strong|ul|ol|li)\s*\/?>$/i.test(t))) throw new Error('HTML fora do formato permitido');
  } else parsed.resposta_html = '';
  if (typeof parsed.produto_modulo !== 'string' || typeof parsed.resumo_solicitacao !== 'string') throw new Error('Produto ou resumo ausente');
  if (!Array.isArray(parsed.informacoes_pendentes) || parsed.informacoes_pendentes.some(v => typeof v !== 'string')) throw new Error('Pendências inválidas');
  if (typeof parsed.rascunho_html !== 'string') throw new Error('Rascunho inválido');
  if (parsed.decisao === 'responder' && source.controle_duplicidade_confirmado !== true) throw new Error('Reserva exclusiva não confirmada');
} catch(e) { issue = e.message; }
return {json:{...source,decisao:issue?'revisao_humana':parsed.decisao,categoria:issue?'outros':parsed.categoria,motivo:issue?'Saída da IA requer revisão: '+issue:parsed.motivo,resposta_html:issue?'':parsed.resposta_html,produto_modulo:issue?'':parsed.produto_modulo,resumo_solicitacao:issue?'':parsed.resumo_solicitacao,rascunho_html:issue?'':(parsed.decisao === 'revisao_humana' ? parsed.rascunho_html : ''),informacoes_pendentes:issue?[issue]:parsed.informacoes_pendentes,acao_executada:'classificacao e preparacao; nenhum envio neste no',status_envio:'nao_enviado'}};
